(()=>{const animateWidth=(element,start,end,duration=180)=>{const stepTime=16;const steps=Math.ceil(duration/stepTime);const stepSize=(end-start)/steps;let currentStep=0;const interval=setInterval((()=>{currentStep++;const currentWidth=start+stepSize*currentStep;element.style.width=`${currentWidth}px`;if(currentStep>=steps){element.style.width=`${end}px`;clearInterval(interval)}}),stepTime)};const sidebars={right:{selector:".interface-interface-skeleton__sidebar",el:null,interval:null,callbacks:{open:(sidebar,initial)=>{const savedWidth=localStorage.getItem(`rse_right_sidebar_width`)||sidebar.default;if(initial){sidebar.el.style.width=`${savedWidth}px`;return}animateWidth(sidebar.el,0,parseInt(savedWidth,10))},close:sidebar=>{animateWidth(sidebar.el,sidebar.el.offsetWidth,0)}},resizable:{handles:"w",start:null,stop:null,resize:sidebar=>(event,ui)=>{sidebar.el.style.left=0;localStorage.setItem(`rse_right_sidebar_width`,sidebar.el.offsetWidth)}},toggleSelectors:['button[aria-controls="edit-post:document"]','button[aria-controls="edit-post:block"]'],default:280},left:{selector:".interface-interface-skeleton__secondary-sidebar",el:null,interval:null,callbacks:{open:(sidebar,initial)=>{const savedWidth=localStorage.getItem(`rse_${sidebar.side}_sidebar_width`)||sidebar.default;const setSavedWidth=()=>{const weirdo=sidebar.el.querySelector(':scope > div > div[aria-hidden="true"]');console.debug(weirdo,savedWidth);initial?weirdo.style.width=`${savedWidth}px`:animateWidth(weirdo,0,parseInt(savedWidth,10))};if(document.body.contains(sidebar.el)){setSavedWidth();return}sidebar.interval=setInterval((function(){sidebar.el=document.querySelector(sidebar.selector);if(!sidebar.el){return}clearInterval(sidebar.interval);setSavedWidth();jQuery(sidebar.el).resizable({handles:sidebar.resizable.handles,start:sidebar.resizable.start?.call(null,sidebar),stop:sidebar.resizable.stop?.call(null,sidebar),resize:sidebar.resizable.resize.call(null,sidebar)})}),100)},close:sidebar=>{}},resizable:{handles:"e",start:null,stop:null,resize:sidebar=>(event,ui)=>{sidebar.el.style.right=0;localStorage.setItem(`rse_${sidebar.side}_sidebar_width`,sidebar.el.offsetWidth)}},toggleSelectors:[".editor-document-tools__document-overview-toggle",".editor-document-tools__inserter-toggle",".block-editor-inserter__quick-inserter-expand"],default:350}};const determineIfSidebarOpen=(selectors,side,initial=false)=>{const elements=selectors.map((selector=>document.querySelector(selector))).filter((el=>el?.classList.contains("is-pressed")));if(elements.length>0){sidebars[side].callbacks.open.call(null,sidebars[side],initial);return true}sidebars[side].callbacks.close.call(null,sidebars[side],initial);return false};window.onload=()=>{for(const side in sidebars){sidebars[side].interval=setInterval((function(){sidebars[side].el=document.querySelector(sidebars[side].selector);if(!sidebars[side].el){return}clearInterval(sidebars[side].interval);determineIfSidebarOpen(sidebars[side].toggleSelectors,side,true);document.addEventListener("click",(e=>{[...document.querySelectorAll(sidebars[side].toggleSelectors)].filter((el=>el!==null)).forEach((selector=>{if(selector.contains(e.target)){determineIfSidebarOpen(sidebars[side].toggleSelectors,side)}}))}));jQuery(sidebars[side].el).resizable({handles:sidebars[side].resizable.handles,start:sidebars[side].resizable.start?.call(null,sidebars[side]),stop:sidebars[side].resizable.stop?.call(null,sidebars[side]),resize:sidebars[side].resizable.resize.call(null,sidebars[side])})}),100)}}})();